import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Input, Row, Button, Spin } from 'antd'

import { AddProviderStyle } from './index.style'
import providerAction from '../../../redux/provider/actions'

const { addProvider } = providerAction

const FormItem = Form.Item

class AddProvider extends Component {
  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        this.props.addProvider({
          body: values
        })
      }
    })
  }

  render () {
    const { form, addProviderLoading } = this.props
    const { getFieldDecorator } = form

    return (
      <AddProviderStyle>
        <Spin spinning={!!addProviderLoading}>
          <Form onSubmit={this.handleSubmit}>
            <FormItem label='Provider Name'>
              {getFieldDecorator('name', {
                rules: [
                  { required: true, message: 'Name can not be empty' }
                ]
              })(
                <Input
                  placeholder='Provider Name'
                />
              )}
            </FormItem>
            <FormItem label='Contact Name'>
              {getFieldDecorator('contact_name', {
                rules: [
                  { required: true, message: 'contact_name can not be empty' }
                ]
              })(
                <Input placeholder='Contact Name' />
              )}
            </FormItem>
            <FormItem label='Contact Phone'>
              {getFieldDecorator('contact_phone', {
                rules: [
                  { required: true, message: 'Contact Phone can not be empty' }
                ]
              })(
                <Input placeholder='Contact Phone' />
              )}
            </FormItem>
            <FormItem label='Contact Email'>
              {getFieldDecorator('contact_email', {
                rules: [
                  { required: true, message: 'Contact Email can not be empty' },
                  { regex: /^[0-9]{8,15}$/ }
                ]
              })(
                <Input placeholder='Contact Email' type='email' />
              )}
            </FormItem>
            <Row type='flex' justify='end'>
              <FormItem>
                <Button
                  type='primary'
                  htmlType='submit'
                >
                  Submit
                </Button>
              </FormItem>
            </Row>
          </Form>
        </Spin>
      </AddProviderStyle>
    )
  }
}

const AddProviderWrapper = Form.create()(AddProvider)

export default connect(state => ({
  addProviderLoading: state.Loading.ADD_PROVIDER
}), {
  addProvider
})(AddProviderWrapper)
