import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import { Card, Table, Icon, Row, Col, Button, Modal, notification, Input } from 'antd'

import { ProviderListStyle } from './index.style'
import providerAction from '../../../redux/provider/actions'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'
import AddProvider from './addProvider'

const { getProviderList } = providerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class ProviderList extends Component {
  state = {
    showAddProviderModal: false
  }

  componentDidMount () {
    this.props.getProviderList()
    this.props.resetLoadingRedux(['ADD_PROVIDER'])
    this.props.resetErrorRedux(['ADD_PROVIDER'])
  }

  componentWillReceiveProps (nextProps) {
    const { addProviderLoading, addProviderError, addProviderMessage } = nextProps
    if (addProviderLoading === false) {
      notification[addProviderError ? 'error' : 'success']({ message: addProviderMessage })
      if (addProviderError === false) {
        this.setState({ showAddProviderModal: false })
      }
      this.props.resetLoadingRedux(['ADD_PROVIDER'])
      this.props.resetErrorRedux(['ADD_PROVIDER'])
    }
  }

  getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button onClick={() => this.handleReset(clearFilters)} size='small' style={{ width: 90 }}>
          Reset
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    }
  })

  handleSearch = (selectedKeys, confirm, dataIndex) => {
    confirm()
    this.setState({
      searchText: selectedKeys[0],
      searchedColumn: dataIndex
    })
  }

  handleReset = clearFilters => {
    clearFilters()
    this.setState({ searchText: '' })
  }

  render () {
    const { getProviderListLoading, providerList = [] } = this.props
    const { showAddProviderModal } = this.state
    const columns = [{
      title: 'Action',
      key: 'action',
      dataIndex: 'code',
      align: 'center',
      render: code => <Icon className='view-icon' type='eye' onClick={() => this.props.history.push(`/provider/${code}`)} />
    }, {
      title: 'Name',
      key: 'name',
      dataIndex: 'name',
      ...this.getColumnSearchProps('name')
    }, {
      title: 'Code',
      key: 'code',
      dataIndex: 'code',
      ...this.getColumnSearchProps('code')
    }, {
      title: 'Status',
      key: 'status',
      dataIndex: 'status'
    }, {
      title: 'Created At',
      key: 'created_at',
      dataIndex: 'created_at',
      render: value => moment(value).format('lll')
    }]

    return (
      <ProviderListStyle>
        <Modal
          visible={showAddProviderModal}
          title='Add Provider'
          footer={null}
          onCancel={() => this.setState({ showAddProviderModal: false })}
        >
          <AddProvider />
        </Modal>
        <Card>
          <Row type='flex' justify='space-between'>
            <Col className='header'>
              Providers List
            </Col>
            <Col>
              <Button
                type='primary'
                icon='plus'
                onClick={() => this.setState({ showAddProviderModal: true })}
              >
                Add Provider
              </Button>
            </Col>
          </Row>
          <Table
            dataSource={providerList}
            columns={columns}
            loading={!!getProviderListLoading}
            bordered
          />
        </Card>
      </ProviderListStyle>
    )
  }
}

export default connect(state => ({
  getProviderListLoading: state.Loading.GET_PROVIDER_LIST,
  providerList: state.Provider.providerList,

  addProviderLoading: state.Loading.ADD_PROVIDER,
  addProviderError: state.Error.ADD_PROVIDER,
  addProviderMessage: state.Provider.addProviderMessage
}), {
  getProviderList,
  resetLoadingRedux,
  resetErrorRedux
})(ProviderList)
